// Actual ExperienceService matrix: absence is not JSON null or another falsy value.
import {createRequire} from 'node:module';import {pathToFileURL} from 'node:url';import {readFileSync,writeFileSync} from 'node:fs';import {createHash} from 'node:crypto';
if(process.version!=='v24.22.1')throw Error('source_node_version_mismatch');const root=process.argv[2];const load=p=>import(pathToFileURL(root+'/'+p));const Database=createRequire(root+'/package.json')('better-sqlite3');
const {SourceEventStore}=await load('src/memory/storage/event-revisions.ts');const {ExperienceService}=await load('src/memory/experience/service.ts');const {validateExperiencePolicy}=await load('src/memory/experience/validation.ts');const {qualificationHash}=await load('src/memory/recovery/domain-contracts.ts');
const values=[['missing',undefined],['null',null],['false',false],['true',true],['zero',0],['number',1.9],['empty-string',''],['string','event'],['empty-array',[]],['array',[null,1,{extra:true}]],['empty-object',{}],['valid-object',{eventId:'source-event',revision:1,deletionEpoch:0}],['fractional-object',{eventId:'source-event',revision:1.9,deletionEpoch:0}],['extra-object',{eventId:'source-event',revision:1,deletionEpoch:0,extra:{historical:'retain'}}]];
const cases=[];const scope={sceneId:'scene',simulation:false};
for(const side of ['source','target'])for(const registered of [false,true])for(const snapshot of [false,true])for(const [name,value] of values){
 const db=new Database(':memory:');const identity={sceneId:'scene',adapterId:'synthetic',accountId:'account',messageId:side==='source'?'instruction':'intro',senderId:side==='source'?'alice':'bot'};
 if(registered)new SourceEventStore(db,{id:()=> 'source-event',now:()=> '2026-10-29T00:00:00.000Z'}).observe({kind:'ingress',identity,bodyHash:'a'.repeat(64),occurredAt:null});let serial=0;
 const service=new ExperienceService(db,{settings:()=>({enabled:true,hints:false,autoActivate:false,feedbackTrials:true,revision:1}),learningEnabled:()=>true,sceneAvailable:()=>true,admissionSourceAvailable:()=>true,targetAvailable:()=>true,sourceRevoked:()=>false,validate:validateExperiencePolicy,now:()=>1793232000000,id:()=>`id${++serial}`});
 const feedback={source:{messageId:'instruction',senderId:'alice'},target:{messageId:'intro'},code:snapshot?'request_exact_person_lookup':'request_conclusion_first',observedAt:'2026-10-29T00:00:00.000Z'};if(name!=='missing')feedback[side].eventRef=value;
 let accepted=true,outcome=null,qualification=null,error=null;try{outcome=service.recordFeedback(scope,feedback).outcome;qualification=qualificationHash(outcome)}catch(e){accepted=false;error=e.message.startsWith('experience_')?e.message:'source_ref_schema_rejection'}
 const count=db.prepare('SELECT count(*) n FROM memory_experience_outcomes').get().n;cases.push({name,side,registered,snapshot,feedback,accepted,outcome,qualification,error,count});db.close();
}
const files=['src/memory/experience/service.ts','src/memory/experience/outcomes.ts','src/memory/storage/event-revisions.ts','src/memory/domain/events.ts','src/memory/recovery/domain-contracts.ts'];const hashes=Object.fromEntries(files.map(p=>[p,createHash('sha256').update(readFileSync(root+'/'+p)).digest('hex')]));writeFileSync(new URL('presence-oracle.json',import.meta.url),JSON.stringify({node:process.version,hashes,cases},null,2)+'\n');
